<section class="rounded-xl border border-sky-300/20 bg-sky-300/5 p-4"><h2 class="text-lg font-semibold">{{ ucfirst($period) }} Punctuality</h2><p class="mt-1 text-xs text-brand-ash">On-time first arrivals as a share of days with a recorded clock-in. Missing days are shown separately. Staff filters select the roster; Late / On Time also filter the detailed logs. Summary percentages retain the selected staff’s full period records.</p><div class="mt-4 space-y-4" tabindex="0" aria-label="Staff punctuality chart">@forelse($summary as $row)<div class="grid min-w-0 gap-2 sm:grid-cols-[minmax(8rem,1fr)_2fr]"><div class="break-words text-sm">{{ $row['name'] }}<span class="block text-xs text-brand-ash">{{ $row['days'] }} recorded days · {{ $row['expected'] }} expected weekdays · {{ $row['late'] }} late · {{ count($row['missing']) }} missing days · {{ round($row['overtime']/60,1) }} overtime hrs</span></div><div><p class="mb-2 text-xs {{ $row['today_status']==='Not Clocked In'?'text-amber-200':'text-brand-ash' }}">Today: {{ $row['today_status'] }}{{ $row['today_in']?' · '.$row['today_in']->format('H:i'):'' }}</p><div class="mb-1 text-sm">{{ $row['punctuality']===null?'No Clock-ins This Period':$row['punctuality'].'% On Time' }}</div>@if($row['punctuality']!==null)<div role="meter" aria-label="{{ $row['name'] }} punctuality" aria-valuemin="0" aria-valuemax="100" aria-valuenow="{{ $row['punctuality'] }}" class="h-3 overflow-hidden rounded-full bg-brand-white/10"><div class="h-full rounded-full bg-sky-400" style="width:{{ $row['punctuality'] }}%"></div></div>@endif @if(count($row['missing']))<details class="mt-2 text-xs"><summary class="cursor-pointer text-amber-200">{{ count($row['missing']) }} missing clock-in dates</summary><p class="mt-2 break-words text-brand-ash">{{ implode(', ',array_map(fn($date)=>\Illuminate\Support\Carbon::parse($date)->format('d M Y'),$row['missing'])) }}</p></details>@endif</div></div>@empty<p>No eligible staff match these filters.</p>@endforelse</div></section>
<section class="rounded-xl border border-brand-white/15 p-4"><h2 class="text-lg font-semibold">Clock-in & Working Hours</h2><p class="mt-1 text-xs text-brand-ash">Recorded clock-ins only. Staff without a clock-in are listed in the full punctuality roster above.</p><div class="mt-3 overflow-x-auto" tabindex="0" role="region" aria-label="Attendance logs"><table class="w-full text-left text-sm"><thead><tr>@foreach(['Staff','Clock-in','Clock-out','Late Minutes','Working Hours','Overtime Hours','Break Allowance'] as $heading)<th class="whitespace-nowrap border-b border-brand-white/20 p-3">{{ $heading }}</th>@endforeach</tr></thead><tbody>@forelse($logs as $log)<tr><td class="p-3">{{ $log->user?->name??'Former staff' }}</td><td class="whitespace-nowrap p-3">{{ $log->clock_in_at->format('d M Y H:i') }}</td><td class="whitespace-nowrap p-3">{{ $log->clock_out_at?->format('d M Y H:i')??'Not Clocked Out' }}</td><td class="p-3">{{ max(0,(int)$log->clock_in_at->copy()->setTime(9,0)->diffInMinutes($log->clock_in_at,false)) }}</td><td class="p-3">{{ $log->scheduledWorkingMinutes()===null?'Pending':round($log->scheduledWorkingMinutes()/60,2) }}</td><td class="p-3">{{ $log->clock_out_at?round(($log->overtime_minutes??0)/60,2):'Pending' }}</td><td class="whitespace-nowrap p-3">60 minutes<span class="block text-xs text-brand-ash">30 min break + 30 min lunch</span></td></tr>@empty<tr><td colspan="7" class="p-3">No matching records.</td></tr>@endforelse</tbody></table></div><div class="mt-4">{{ $logs->links() }}</div></section>
